import re,subprocess,glob,os
text='\n'.join(open('docs/CODE-LAYOUT.md').read().split('\n')[179:])
ids=set(re.findall(r'`([A-Za-z_][A-Za-z0-9_$]{4,})`', text))
# build corpus of public/ and src/ sources
corpus=''
for root in ('public','src','sdk','scripts'):
    for dp,dn,fn in os.walk(root):
        if 'introspect' in dp or 'vendor' in dp: continue
        for f in fn:
            if f.endswith(('.js','.mjs','.html','.css','.json')):
                try: corpus+=open(os.path.join(dp,f),errors='ignore').read()
                except: pass
miss=sorted(x for x in ids if x not in corpus)
print(len(ids),'ids;',len(miss),'missing')
for m in miss: print(' ',m)

